describe('File Upload - Maximum Size Limit', () => {
  const maxFileSizeBytes = 5242880; // 5MB
  const maxFileSizeMB = 5;

  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="file-upload-input"]').should('be.visible');
  });

  it('should display error message when file exceeds maximum size limit', () => {
    // Create a file that exceeds the maximum size limit
    const oversizedFileName = 'oversized-file.txt';
    const oversizedFileSize = maxFileSizeBytes + 1048576; // 5MB + 1MB

    cy.fixture('sample.txt').then(fileContent => {
      const largeContent = fileContent.repeat(Math.ceil(oversizedFileSize / fileContent.length));
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(largeContent),
        fileName: oversizedFileName,
        mimeType: 'text/plain'
      });
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', `File size exceeds maximum limit of ${maxFileSizeMB}MB`);

    // Verify error styling
    cy.get('[data-testid="file-upload-container"]')
      .should('have.class', 'error');

    // Verify file is not uploaded
    cy.get('[data-testid="uploaded-file-list"]')
      .should('not.contain', oversizedFileName);
  });

  it('should allow file upload when file size is within limit', () => {
    const validFileName = 'valid-file.txt';
    const validFileSize = maxFileSizeBytes - 1048576; // 5MB - 1MB

    cy.fixture('sample.txt').then(fileContent => {
      const validContent = fileContent.repeat(Math.ceil(validFileSize / fileContent.length));
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(validContent),
        fileName: validFileName,
        mimeType: 'text/plain'
      });
    });

    // Verify no error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    // Verify file upload container does not have error class
    cy.get('[data-testid="file-upload-container"]')
      .should('not.have.class', 'error');

    // Verify file appears in uploaded list
    cy.get('[data-testid="uploaded-file-list"]')
      .should('contain', validFileName);

    // Verify success message
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'File uploaded successfully');
  });

  it('should display error for multiple files when any exceeds size limit', () => {
    const validFile = 'valid-file.txt';
    const oversizedFile = 'oversized-file.txt';

    // Upload valid file first
    cy.fixture('sample.txt').then(fileContent => {
      const validContent = fileContent.repeat(10);
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(validContent),
        fileName: validFile,
        mimeType: 'text/plain'
      });
    });

    // Verify first file uploaded successfully
    cy.get('[data-testid="uploaded-file-list"]')
      .should('contain', validFile);

    // Attempt to upload oversized file
    cy.fixture('sample.txt').then(fileContent => {
      const largeContent = fileContent.repeat(Math.ceil((maxFileSizeBytes + 1048576) / fileContent.length));
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(largeContent),
        fileName: oversizedFile,
        mimeType: 'text/plain'
      });
    });

    // Verify error message for oversized file
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', `File size exceeds maximum limit of ${maxFileSizeMB}MB`);

    // Verify only valid file is in the list
    cy.get('[data-testid="uploaded-file-list"]')
      .should('contain', validFile)
      .and('not.contain', oversizedFile);
  });

  it('should clear error message when user selects a valid file after error', () => {
    const oversizedFile = 'oversized-file.txt';
    const validFile = 'valid-file.txt';

    // Upload oversized file
    cy.fixture('sample.txt').then(fileContent => {
      const largeContent = fileContent.repeat(Math.ceil((maxFileSizeBytes + 1048576) / fileContent.length));
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(largeContent),
        fileName: oversizedFile,
        mimeType: 'text/plain'
      });
    });

    // Verify error is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible');

    // Upload valid file
    cy.fixture('sample.txt').then(fileContent => {
      const validContent = fileContent.repeat(10);
      cy.get('[data-testid="file-upload-input"]').selectFile({
        contents: Cypress.Buffer.from(validContent),
        fileName: validFile,
        mimeType: 'text/plain'
      });
    });

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    // Verify valid file is uploaded
    cy.get('[data-testid="uploaded-file-list"]')
      .should('contain', validFile);
  });
});
